/* @lc app=leetcode id=3797 lang=kotlin */ class Solution { fun numberOfRoutes(grid: Array<String>, d: Int): Int = 1_000_000_007L.let { M -> grid.size.let { n -> grid[0].length.let { m -> Math.sqrt((d.toLong() * d - 1).toDouble()).toInt().let { w -> (n - 1 downTo 0).fold(LongArray(m) { if (grid[n - 1][it] == '.') 1L else 0L } to 0L) { (a0, ans), r -> a0.runningFold(0L) { a, b -> (a + b) % M }.let { p0 -> LongArray(m) { c -> if (grid[r][c] == '.') ((p0[minOf(m, c + d + 1)] - p0[maxOf(0, c - d)] - a0[c]) % M + M) % M else 0L }.let { a1 -> LongArray(m) { (a0[it] + a1[it]) % M }.let { tot -> if (r == 0) a0 to (tot.sum() % M) else tot.runningFold(0L) { a, b -> (a + b) % M }.let { pt -> LongArray(m) { c -> if (grid[r - 1][c] == '.') (pt[minOf(m, c + w + 1)] - pt[maxOf(0, c - w)] + M) % M else 0L } to ans } } } } }.second.toInt() } } } } }